for order in self:
    lines = order.order_line.filtered(lambda l: not l.display_type)
    order['x_total_discount_amount'] = sum(l.price_unit * l.product_uom_qty - l.price_subtotal for l in lines if l.discount)

for wizard in records:
    order_lines = wizard.sale_order_id.order_line.filtered(lambda l: not l.display_type and l.price_unit * l.product_uom_qty)
    if not order_lines or not (total_amount := sum(order_lines.mapped('price_subtotal'))):
        continue
    for line in order_lines:
        line['discount'] = 100 * (wizard.discount_amount / total_amount)
action = {'type': 'ir.actions.act_window_close'} # short-circuit the modal to not apply the discount normally
